param([Parameter(Mandatory=$true)][string]$Ymm4Dir,[Parameter(Mandatory=$true)][string]$OutputDir)
$ErrorActionPreference='Stop';New-Item -ItemType Directory -Force $OutputDir|Out-Null;$r=Join-Path $OutputDir 'result.txt'
Add-Type -TypeDefinition @'
using System;using System.Text;using System.Runtime.InteropServices;public static class W{public delegate bool E(IntPtr h,IntPtr l);[DllImport("user32.dll")]public static extern bool EnumWindows(E c,IntPtr l);[DllImport("user32.dll")]public static extern bool IsWindowVisible(IntPtr h);[DllImport("user32.dll",CharSet=CharSet.Unicode)]public static extern int GetWindowText(IntPtr h,StringBuilder t,int m);[DllImport("user32.dll")]public static extern bool PostMessage(IntPtr h,uint m,IntPtr w,IntPtr l);}
'@
function Wins{$script:x=@();$c=[W+E]{param([IntPtr]$h,[IntPtr]$l)if([W]::IsWindowVisible($h)){$s=New-Object System.Text.StringBuilder 1024;[void][W]::GetWindowText($h,$s,$s.Capacity);if($s.Length){$script:x+=[pscustomobject]@{H=$h;T=$s.ToString()}}};return $true};[void][W]::EnumWindows($c,[IntPtr]::Zero);$script:x}
$env:CNWL_YMM4_NO_HARMONY_FILEDROP_DIR=$OutputDir;$p=Start-Process (Join-Path $Ymm4Dir 'YukkuriMovieMaker.exe') -WorkingDirectory $Ymm4Dir -PassThru
try{for($i=0;$i-lt180;$i++){if(Test-Path $r){break};foreach($w in (Wins)){if($w.T-like'*Check for updates*'-or$w.T-like'*About YukkuriMovieMaker*'){[void][W]::PostMessage($w.H,0x10,[IntPtr]::Zero,[IntPtr]::Zero)}elseif($w.T-eq'Confirm'){[void][W]::PostMessage($w.H,0x100,[IntPtr]0x0D,[IntPtr]::Zero);[void][W]::PostMessage($w.H,0x101,[IntPtr]0x0D,[IntPtr]::Zero)}};Start-Sleep -Milliseconds 500};if(-not(Test-Path $r)){throw'no result'};Get-Content $r;if(-not((Get-Content $r)-contains'status=PASS_NO_HARMONY_FILEDROP_OBSERVATION')){throw'probe failed'}}finally{if(-not$p.HasExited){Stop-Process $p.Id -Force -ErrorAction SilentlyContinue};Remove-Item Env:CNWL_YMM4_NO_HARMONY_FILEDROP_DIR -ErrorAction SilentlyContinue}